H.background();
const cx = H.W * 0.5, cy = H.H * 0.54, R = Math.min(H.W, H.H) * 0.32;
const a = Math.max(0.2, P.a), k = Math.max(1, Math.round(P.k)), b = P.b;
// polar curve r(theta) = a*cos(k*theta) + b  (rose / limaçon family)
const rOf = (th) => a * Math.cos(k * th) + b;
// scale so the largest radius fits the circle
const rMax = Math.max(0.5, a + Math.abs(b));
const sc = R / rMax;
// faint polar grid rings + axes
for (let ring = 1; ring <= 3; ring++) H.circle(cx, cy, R * ring / 3, { stroke: H.colors.grid, width: 1 });
H.line(cx - R - 14, cy, cx + R + 14, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - R - 14, cx, cy + R + 14, { color: H.colors.axis, width: 1 });
// draw the curve
const pts = [];
for (let i = 0; i <= 360; i++) {
  const th = i / 360 * H.TAU;
  const r = rOf(th);
  pts.push([cx + r * sc * Math.cos(th), cy - r * sc * Math.sin(th)]);
}
H.path(pts, { color: H.colors.accent, width: 2.5 });
